seed.content:
def extract_config(settings, prefix):
    config = {}
    for key in settings.keys():
        if key.startswith(prefix):
            value = settings[key]
            config[key[len(prefix):]] = value
    return config

if __name__ == "__main__":
    assert extract_config({"db_host": "x", "db_port": 5432, "cache_ttl": 60}, "db_") == {"host": "x", "port": 5432}
    assert extract_config({}, "app_") == {}
    print("behavior preserved")
